# ── Cell 2: Imports + yard parser (identical to MoveHistory_Silver_CT03) ───────
import re
from pyspark.sql import functions as F
from pyspark.sql.window import Window
from pyspark.sql.types import StructType, StructField, StringType, ShortType, IntegerType
from delta.tables import DeltaTable

def _make_parser(code, tier_type="numeric"):
    prefix = f"Y-{code}-"
    return {
        "yard_prefix"    : prefix,
        "yard_pattern"   : re.compile(rf"^{re.escape(prefix)}(\d?[A-Z]{{1,2}})(\d{{2,3}})([A-Z])(\d{{1,2}})$"),
        "special_pattern": re.compile(r"^[A-Z][A-Z0-9_]*$"),
        "groups"         : {"block": 1, "bay": 2, "row": 3, "tier": 4},
        "tier_type"      : tier_type,
    }

TERMINAL_PARSERS = {"CT03": _make_parser("CT03")}
DEFAULT_PARSER = "CT03"
POSITION_PREFIX_TYPE = {"Y": "YARD", "V": "VESSEL", "T": "TRUCK"}
_ALPHA_TO_NUM = {ch: i + 1 for i, ch in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ")}

def _normalize_tier(raw, tier_type):
    if raw is None or raw == "":
        return None
    if tier_type == "alpha":
        return _ALPHA_TO_NUM.get(str(raw).upper())
    try:
        return int(raw)
    except (ValueError, TypeError):
        return None

def _parse(pos):
    cfg = TERMINAL_PARSERS.get(TERMINAL_CODE, TERMINAL_PARSERS[DEFAULT_PARSER])
    if not pos or not str(pos).startswith(cfg["yard_prefix"]):
        return (None, None, None, None, 0)
    pos = str(pos).strip()
    m = cfg["yard_pattern"].match(pos)
    if m:
        g = cfg["groups"]
        t = _normalize_tier(m.group(g["tier"]), cfg["tier_type"])
        return (m.group(g["block"]), m.group(g["bay"]), m.group(g["row"]),
                int(t) if t is not None else None, 0)
    code = pos.replace(cfg["yard_prefix"], "", 1)
    if cfg["special_pattern"].match(code):
        return (code, None, "Buffer", None, 0)
    return (None, None, None, None, 1)

_PARSE_SCHEMA = StructType([
    StructField("block", StringType()), StructField("bay", StringType()),
    StructField("row", StringType()),   StructField("tier", ShortType()),
    StructField("parse_fail", IntegerType()),
])

@F.udf(returnType=_PARSE_SCHEMA)
def parse_position_udf(pos):
    return _parse(pos)

